#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: HTTPS for dedupendnote.nl on the STRATO VPS (Plesk, Ubuntu 22.04)
# Issue #127. Run this ON THE SERVER over SSH (as the normal user with sudo).
# Runbook with the same steps and undo notes: docs/https-setup.md
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8
DOMAIN="dedupendnote.nl"
ENV_FILE="${ENV_FILE:-$HOME/.dedupendnote-https.env}"

# show CMD...: print the command, then its output (never fails the wizard).
show() {
  printf '\n  %s$ %s%s\n' "$DIM" "$*" "$RESET"
  { "$@" 2>&1 || true; } | sed 's/^/    /'
}

banner "HTTPS for $DOMAIN via Plesk"
warn "Stages 1-2 change nothing on the server (read-only, plus one backup file)."
note "Remembered answers are saved in $ENV_FILE"

# ── 1. Read-only inventory ────────────────────────────────────────────────
stage "Look around (read-only)"
say "We only look. Nothing is changed."
show lsb_release -ds
show sudo ss -tlnp
show sudo ufw status
show sudo iptables -t nat -S
show sudo ip6tables -t nat -S
show bash -c 'ls -l /etc/iptables/rules.v4 /etc/iptables/rules.v6 2>&1; grep -s -n "9777\|REDIRECT" /etc/iptables/rules.v4 /etc/iptables/rules.v6'
show bash -c 'command -v plesk >/dev/null && plesk version || echo "plesk command not found"'
echo
step "Read the 'ss -tlnp' output above."
say "Expected: nginx (Plesk) on :80 and :443, java on :9777, sshd on :22."
warn "STOP and tell Claude if another program than nginx/apache uses :80 or :443,"
warn "or if iptables/rules.v4 contains a REDIRECT or 9777 line."
confirm "Does the output look as expected (nothing odd on :80/:443, no REDIRECT rule)?" \
  || { say "Stopped. Paste the output above to Claude. Nothing was changed."; exit 1; }

# ── 2. Backup ─────────────────────────────────────────────────────────────
stage "Backup (one file in your home directory)"
say "Plesk's daily backup does not cover directories outside Plesk (like the app)."
show bash -c 'ps -eo pid,user,args | grep "[d]edupendnote\|[.]jar"'
ask APP_DIR "Directory that holds the DedupEndNote jar (e.g. /opt/dedupendnote):"
[[ -d "$APP_DIR" ]] || { warn "$APP_DIR is not a directory"; exit 1; }
STAMP=$(date +%Y%m%d-%H%M)
BACKUP="$HOME/dedupendnote-backup-$STAMP.tgz"
INV="$HOME/dedupendnote-inventory-$STAMP.txt"
{ date; echo '--- crontab'; crontab -l 2>&1 || true
  echo '--- ss'; sudo ss -tlnp 2>&1 || true
  echo '--- ufw'; sudo ufw status verbose 2>&1 || true
  echo '--- iptables nat'; sudo iptables -t nat -S 2>&1 || true
} > "$INV"
tar czf "$BACKUP" "$APP_DIR" "$INV" 2>/dev/null || true
[[ -s "$BACKUP" ]] || { warn "backup file is empty or missing: $BACKUP"; exit 1; }
write_env APP_DIR "$APP_DIR"
say "Backup written: $BACKUP ($(du -h "$BACKUP" | cut -f1))"
note "Restore later with: sudo tar xzf $BACKUP -C /"
step "Optional: copy it to your PC, e.g.  scp user@server:$BACKUP ."
pause "Press Enter when ready"

# ── 3. DNS ────────────────────────────────────────────────────────────────
stage "DNS check"
ask SERVER_IP "Public IP of this VPS (shown in the STRATO portal):"
write_env SERVER_IP "$SERVER_IP"
show dig +short "$DOMAIN" A
show dig +short "www.$DOMAIN" A
DNS_IP=$(dig +short "$DOMAIN" A | tail -n1 || true)
if [[ "$DNS_IP" != "$SERVER_IP" ]]; then
  warn "DNS says '$DNS_IP' but you said '$SERVER_IP'. Let's Encrypt would fail."
  exit 1
fi
say "OK: $DOMAIN points at $SERVER_IP. (No www record: we skip www, as agreed.)"
pause "Press Enter to continue"

# ── 4. Make ports 80/443 reachable ────────────────────────────────────────
stage "Ports 80 and 443 from the internet"
say "Let's Encrypt needs port 80 reachable from outside. Your browser test said unreachable."
show sudo ufw status
if sudo ufw status 2>/dev/null | grep -q "Status: active"; then
  warn "ufw is ACTIVE. If 80/443 are not listed as ALLOW, they are blocked at OS level."
  step "Rules that would be added:  sudo ufw allow 80/tcp  and  sudo ufw allow 443/tcp"
  if confirm "Add these two ufw rules now?"; then
    sudo ufw allow 80/tcp
    sudo ufw allow 443/tcp
    show sudo ufw status
    note "Undo: sudo ufw delete allow 80/tcp ; sudo ufw delete allow 443/tcp"
  fi
else
  say "ufw is not active, so the OS firewall is not what blocks 80/443."
fi
step "Plesk firewall (only if the Firewall extension is installed):"
open_url "https://$SERVER_IP:8443"
say "  Tools & Settings → Firewall → HTTP (80) and HTTPS (443) must be allowed."
say "  (The browser warns about the certificate on :8443; that is normal for Plesk.)"
step "The STRATO portal firewall already allows 80/443 (you checked)."
echo
say "Test from OUTSIDE the server (your PC, or your phone on mobile data):"
open_url "http://$DOMAIN"
say "  Any page (even a Plesk default page or a 404) = reachable. Timeout = still blocked."
confirm "Is http://$DOMAIN reachable now (any page, not a timeout)?" \
  || { say "Still blocked. Paste the stage 1 and 4 output to Claude. Nothing else changed."; exit 1; }

# ── 5. Plesk: add the domain, then the certificate ────────────────────────
stage "Plesk: add the domain"
open_url "https://$SERVER_IP:8443"
step "Websites & Domains → Add Domain → 'Blank website'"
step "Domain name: $DOMAIN   (hosting type: Website hosting; any system user/password)"
step "Untick 'Include www' / 'Create DNS zone' if shown (DNS stays at STRATO)."
step "Then: Mail → Mail Settings for the domain → UNTICK 'Activate mail service on domain'"
say "  (Otherwise the server would try to deliver mail for $DOMAIN locally.)"
note "Undo: Websites & Domains → $DOMAIN → Remove Website."
pause "Press Enter when the domain exists and mail service is off"

stage "Plesk: Let's Encrypt certificate"
step "Websites & Domains → $DOMAIN → SSL/TLS Certificates → Install (Let's Encrypt)"
step "Email: your own address. UNTICK 'Include a www subdomain'. Tick 'Secure the domain name'."
step "Leave wildcard unticked. Click 'Get it free'."
step "Then Hosting Settings → tick 'Permanent SEO-safe 301 redirect from HTTP to HTTPS' → OK."
say "A green 'successfully issued' message = done."
note "Undo: remove the certificate under SSL/TLS Certificates and untick the redirect."
pause "Press Enter when the certificate is issued"
show curl -sSI "https://$DOMAIN" --max-time 15
confirm "Did that show an HTTP status line (200, 403, 404...), not a certificate or connection error?" \
  || { say "Paste the curl output to Claude."; exit 1; }

# ── 6. Plesk: proxy to the app ────────────────────────────────────────────
stage "Plesk: proxy $DOMAIN to the app on :9777"
step "Websites & Domains → $DOMAIN → Apache & nginx Settings"
step "UNTICK 'Proxy mode' (and 'Smart static files processing') if they are ticked."
step "In 'Additional nginx directives' paste EXACTLY this block, then click Apply:"
cat <<'NGINX'

    location / {
        proxy_pass http://127.0.0.1:9777;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        client_max_body_size 150m;
        proxy_request_buffering off;
        proxy_read_timeout 1500s;
        proxy_send_timeout 1500s;
    }

NGINX
note "Why: 150m = the app's upload limit (nginx's default 1m would reject RIS files);"
note "1500s > the app's 20-minute run timeout; Upgrade/Connection = WebSocket progress."
warn "If Plesk reports an error such as 'duplicate location \"/\"', it refused the change"
warn "and kept the old config: nothing broke. Paste the error to Claude and stop."
note "Undo: empty the 'Additional nginx directives' box → Apply."
pause "Press Enter when Plesk says the settings were applied"

# ── 7. Verify ─────────────────────────────────────────────────────────────
stage "Verify"
show curl -sSI "https://$DOMAIN/" --max-time 20
show curl -sSI "http://$DOMAIN/" --max-time 20
show curl -sSI "http://127.0.0.1:9777/" --max-time 20
show curl -sS "https://$DOMAIN/gs-guide-websocket/info" --max-time 20
echo
say "Expected: https → 200 from the app; http → 301 to https; 9777 still 200;"
say "the last one returns JSON containing \"websocket\":true."
echo
open_url "https://$DOMAIN/"
step "In the browser: upload a small RIS file and run a deduplication."
step "Check: padlock shown, progress messages appear, result downloads."
step "Also try the old URL: http://$DOMAIN:9777/ must still work."
if confirm "Did the full run work over https?"; then
  say "Done. Tell Claude, then the follow-up PR (https in citation.cff/docs) can start."
else
  warn "Rollback: empty 'Additional nginx directives' in Plesk and Apply."
  warn "http://$DOMAIN:9777 never stopped working. Paste what failed to Claude."
fi

finish
}

run_wizard "$@"; exit
